struct string_buf;

class stringx
{
    char *chars;
    string_buf *my_buf;

public:
    stringx(const stringx &);
    ~stringx();
    stringx &operator=(const stringx &);
};

class PanelFile
{
    int slide_state;
    float slide_offset;
    float slide_timer;
    float slide_max_time;
    stringx filename;

public:
    void *obs;
    stringx path;
    PanelFile *next;
    void *pquads;

    PanelFile(stringx f, stringx p);
    virtual ~PanelFile();
} __attribute__((aligned(16)));

class FEManager;

class FrontEnd
{
    char padding[128];

public:
    PanelFile panel;
    FrontEnd *next;
    stringx path;
    FEManager *manager;

    void cons(FEManager *man, stringx p, stringx pf_name);
};

void FrontEnd::cons(FEManager *man, stringx p, stringx pf_name)
{
    panel = PanelFile(pf_name, p);
    manager = man;
    path = p;
}
